 const prev=new Int32Array(grid.length).fill(-1),dist=new Float64Array(grid.length).fill(Infinity),heap=[];
 function push(id,cost){let i=heap.length;heap.push({id,cost});while(i){let p=(i-1)>>1;if(heap[p].cost<=cost)break;heap[i]=heap[p];i=p;}heap[i]={id,cost};}
 function pop(){const first=heap[0],last=heap.pop();if(heap.length){let i=0;while(i*2+1<heap.length){let j=i*2+1;if(j+1<heap.length&&heap[j+1].cost<heap[j].cost)j++;if(heap[j].cost>=last.cost)break;heap[i]=heap[j];i=j;}heap[i]=last;}return first;}
