 while(heap.length){const cur=pop(),i=cur.id;if(cur.cost>dist[i])continue;if(i===end)break;for(const n of neighbours(i,reachable)){const diag=i%COLS!==n%COLS&&Math.floor(i/COLS)!==Math.floor(n/COLS),cost=dist[i]+(diag?Math.SQRT2:1)*(travelCost[n]+travelCost[i])*.5;if(cost<dist[n]){dist[n]=cost;prev[n]=i;push(n,cost);}}}
