function biteAlert(){alertTime=1.4;if(settings.vibration&&typeof navigator.vibrate==='function'){try{navigator.vibrate([80,45,110]);}catch(e){}}
 if(!settings.sound||!biteAudio||biteAudio.state!=='running')return;
 try{const now=biteAudio.currentTime;for(const [hz,delay,volume] of [[1175,0,.10],[1760,.075,.055]]){const tone=biteAudio.createOscillator(),gain=biteAudio.createGain();tone.type='sine';tone.frequency.setValueAtTime(hz,now+delay);gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(volume,now+delay+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.38);tone.connect(gain);gain.connect(fxOutput());tone.start(now+delay);tone.stop(now+delay+.4);}}catch(e){}
}
function nextPull(){pullPhase=pullPhase==='calm'?'surge':'calm';pullTime=pullPhase==='surge'?1.05+Math.random()*.85:.65+Math.random()*.75;pullTarget=pullPhase==='surge'?29+Math.random()*16:6+Math.random()*9;}
function updatePull(dt){pullTime-=dt;if(pullTime<=0)nextPull();pullForce+=(pullTarget-pullForce)*Math.min(1,dt*5);}
function updateRipples(dt){let changed=false;for(const p of rippleSpots)p.age+=dt;const live=rippleSpots.filter(p=>p.age<p.life);if(live.length!==rippleSpots.length){rippleSpots=live;changed=true;}rippleCountdown-=dt;if(rippleCountdown<=0&&rippleSpots.length<2){const available=rippleAreas.filter(a=>rippleSpots.every(p=>Math.hypot(p.x-a.x,p.y-a.y)>70));if(available.length){const a=available[Math.floor(Math.random()*available.length)];rippleSpots.push({x:a.x+(Math.random()-.5)*25,y:a.y+(Math.random()-.5)*20,age:0,life:4.5+Math.random()*2,id:++rippleID});changed=true;}rippleCountdown=7+Math.random()*2;}if(changed){renderRippleTargets();fishHint(rippleSpots.length?'A ripple! Tap it to cast.':'Watch the water for a ripple…');}}
function visitSummary(){const counts=fishSpecies.map(f=>({name:f.name,count:sessionCatches.filter(c=>c.species===f.id).length}));const biggest=sessionCatches.reduce((best,c)=>!best||c.size>best.size?c:best,null);return {total:sessionCatches.length,counts,biggest};}
function leaveFishing(){reeling=false;persist();leavingRecap=true;const recap=visitSummary();modal('A little time well spent',`<p class="recap-total">${recap.total}</p><p class="recap-caption">${recap.total===1?'fish caught this visit':'fish caught this visit'}</p>${recap.counts.filter(c=>c.count).map(c=>`<div class="journal-row">${c.name}<span>${c.count}</span></div>`).join('')}${recap.biggest?`<p><b>Biggest catch</b><br>${fishSpecies.find(f=>f.id===recap.biggest.species).name} · ${recap.biggest.size.toFixed(1)} cm</p>`:'<p>No catches this time. There is always another quiet moment by the water.</p>'}<p class="mini-note">${bucket.length} fish in your bucket altogether. All catches are saved.</p><button class="action gold" id="confirmLeave">Back to the island</button><button class="action" id="stayFishing">Stay a little longer</button>`,'YOUR FISHING RECAP');$('confirmLeave').onclick=()=>{close();fishMode('idle');show('game');};$('stayFishing').onclick=close;}

function resizeFishing(){const r=$('fishingWrap').getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H);Object.assign(fishCanvas.style,{width:W*scale+'px',height:H*scale+'px',left:(r.width-W*scale)/2+'px',top:(r.height-H*scale)/2+'px'});}
new ResizeObserver(resizeFishing).observe($('fishingWrap'));
function fishHint(text){$('fishHint').textContent=text;}
function fishMode(state){fishState=state;fishTimer=0;reeling=false;fishCanvas.style.pointerEvents=['walking','idle','casting','waiting'].includes(state)?'auto':'none';$('reelPanel').classList.toggle('hidden',state!=='reeling');$('rippleTargets').classList.toggle('hidden',state!=='idle');if(state==='idle'){rippleSpots=[];rippleCountdown=1+Math.random();renderRippleTargets();fishHint('Watch the water for a ripple…');}if(state==='walking')fishHint('Finding a good spot on the pier…');if(state==='casting')fishHint('A little further out…');if(state==='waiting')fishHint('Watch the float. Something might be curious.');if(state==='reeling')fishHint('A bite! Hold to reel. Release to ease the tension.');}
function startFishing(){$('rodNote').textContent=`Basic rod · ${economy.owned.line?'strong line · ':''}${economy.stock.bait} bait`;sessionCatches=[];unlockBiteAudio();path=[];fishY=82;fishMode('walking');show('fishing');resizeFishing();$('bucketCount').textContent=bucket.length;renderRippleTargets();}
$('leaveFishing').onclick=leaveFishing;
function renderRippleTargets(){const e=$('rippleTargets');e.innerHTML='';rippleSpots.forEach((p,i)=>{const b=document.createElement('button');b.className='ripple-target';b.setAttribute('aria-label',`Cast at ripple ${p.id}`);b.textContent='';b.onclick=()=>castAt(p);b.dataset.rippleId=p.id;b.style.left=p.x/W*100+'%';b.style.top=p.y/H*100+'%';e.append(b);});const r=$('fishingWrap').getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H);Object.assign(e.style,{width:W*scale+'px',height:H*scale+'px',left:(r.width-W*scale)/2+'px',top:(r.height-H*scale)/2+'px'});}
new ResizeObserver(()=>{resizeFishing();renderRippleTargets();}).observe($('fishingWrap'));
function castAt(p){if(fishState!=='idle'||!rippleSpots.includes(p)||p.age>=p.life)return;unlockBiteAudio();splashAge=-1;castPoint={...p};biteDelay=1.6+Math.random()*1.8;if(economy.stock.bait>0){economy.stock.bait--;biteDelay*=.55;persist();$('rodNote').textContent=`Basic rod · ${economy.stock.bait} bait left`;}fishMode('casting');}
fishCanvas.addEventListener('pointerdown',e=>{if(fishState!=='idle')return;const r=fishCanvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;const p=rippleSpots.find(p=>Math.hypot(x-p.x,y-p.y)<45);if(p)castAt(p);});
function beginBite(){// Both species remain possible on every cast.
 fishOn=fishSpecies[Math.random()<.55?0:1];reelProgress=0;tension=18;lineLocked=false;lastUI=-1;pullPhase='calm';pullTime=.7+Math.random()*.5;pullForce=pullTarget=8+Math.random()*7;fishMode('reeling');biteAlert();updateReelUI();}
function setReeling(e){if(fishState!=='reeling')return;e.preventDefault?.();reeling=true;if(e.pointerId!==undefined)$('reelButton').setPointerCapture?.(e.pointerId);}
$('reelButton').addEventListener('pointerdown',setReeling);for(const type of ['pointerup','pointercancel','lostpointercapture'])$('reelButton').addEventListener(type,()=>{reeling=false;});
$('reelButton').addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter')setReeling(e);});$('reelButton').addEventListener('keyup',()=>{reeling=false;});
function updateReelUI(){const progress=Math.min(100,Math.floor(reelProgress)),tight=Math.round(tension);$('catchProgress').value=progress;$('progressValue').textContent=progress+'%';$('lineTension').value=tight;$('lineTension').classList.toggle('danger',tension>76);$('reelButton').classList.toggle('reeling',reeling&&!lineLocked);$('reelButton').textContent=lineLocked?'Release · let the line relax':reeling?'Reeling…':'Hold to reel';$('reelAdvice').textContent=lineLocked?'Let go until tension falls below 40%.':tension>72?'Getting tight. Ease off for a moment.':reeling?(pullPhase==='surge'?'The fish is pulling harder…':'A gentler pull. Keep it steady.'):'Hold to bring the fish closer.';$('fishPull').textContent=pullPhase==='surge'?'Pulling harder':'Swimming steadily';$('fishPull').classList.toggle('strong-pull',pullPhase==='surge');}
function updateFishing(dt){if(!$('modal').classList.contains('hidden'))return;if(splashAge>=0)splashAge+=dt;fishTimer+=dt;alertTime=Math.max(0,alertTime-dt);if(fishState==='idle')updateRipples(dt);if(fishState==='walking'){fishY=Math.min(182,fishY+dt*55);if(fishY>=182)fishMode('idle');}else if(fishState==='casting'&&fishTimer>=.9){fishMode('waiting');splashAge=0;plopSound();}else if(fishState==='waiting'&&fishTimer>=biteDelay)beginBite();else if(fishState==='reeling'){updatePull(dt);if(reeling&&!lineLocked){reelProgress=Math.min(100,reelProgress+dt*19);tension=Math.min(100,tension+dt*Math.max(3,pullForce+Math.sin(fishTimer*4)*2)*(economy.owned.line?.85:1));if(tension>=94)lineLocked=true;}else{tension=Math.max(10,tension-dt*(reeling?9:34));if(!reeling&&tension<40)lineLocked=false;}updateReelUI();if(reelProgress>=100)landFish();}}
function landFish(){if(fishState!=='reeling')return;const size=Math.round((fishOn.min+Math.random()*(fishOn.max-fishOn.min))*10)/10,caught={species:fishOn.id,size,caughtAt:new Date().toISOString()};const previousBest=economy.records[fishOn.id].best,record=size>previousBest;economy.records[fishOn.id].count++;economy.records[fishOn.id].best=Math.max(previousBest,size);bucket.push(caught);sessionCatches.push(caught);persist();fishMode('caught');$('bucketCount').textContent=bucket.length;fishHint('A lovely catch. Safely in your bucket.');modal('Congratulations!',`<canvas id="catchFish" width="240" height="110" aria-label="Your ${fishOn.name}"></canvas><p class="catch-name">${fishOn.name}</p><p class="catch-size">${size.toFixed(1)} cm</p>${record?`<p class="personal-best">${previousBest?'New personal best!':'First '+fishOn.name.toLowerCase()+'!'}</p>`:''}<p>Added to the bucket beside you.</p><button id="castAgain" class="action gold">Lovely! Keep fishing</button>`,'YOU CAUGHT A FISH');const g=$('catchFish').getContext('2d');drawFish(g,120,52,fishOn,5);$('castAgain').onclick=()=>{close();fishMode('idle');};}
function showBucket(){modal('Your fishing bucket',bucket.length?`<p>${bucket.length} ${bucket.length===1?'fish':'fish'} safely aboard.</p><div class="bucket-list">${bucket.slice().reverse().map(c=>`<div class="journal-row">${fishSpecies.find(f=>f.id===c.species).name}<span>${c.size.toFixed(1)} cm</span></div>`).join('')}</div>`:'<p>Your bucket is empty. Walk to the fishing pier and tap a ripple to make your first cast.</p>','TODAY’S CATCH');}
$('fishBucket').onclick=showBucket;
function drawFish(g,x,y,f,scale=1){g.save();g.translate(x,y);g.scale(scale,scale);function r(c,x,y,w,h){g.fillStyle=c;g.fillRect(x,y,w,h);}r('#35423c',-17,-3,4,6);r(f.colour,-14,-5,26,10);r(f.back,-12,-6,21,3);r('#e8dfb0',-10,2,20,3);r(f.back,-5,-9,7,4);r(f.colour,-21,-7,5,14);r('#292f2c',8,-2,2,2);r('#fff7cf',9,-2,1,1);r(f.back,0,-3,2,5);r(f.back,-5,-3,2,5);r(f.back,-10,-3,2,5);g.restore();}
function drawFishing(t){fg.imageSmoothingEnabled=false;if(fishArtReady){fg.drawImage(fishBase,0,0);movingSurface(fg,fishBase,t,null,250);waterRings(fg,172,238,t,19);waterRings(fg,333,238,t+.7,19);}else{fg.fillStyle='#158cad';fg.fillRect(0,0,W,H);fg.fillStyle='#b88145';fg.fillRect(153,0,206,198);}
 if(settings.ambient){for(let i=0;i<20;i++){const y=255+i*25+((t*9)%25),x=40+(i*101)%400;fg.strokeStyle=`rgba(226,249,229,${.12+Math.sin(t+i)*.06})`;fg.lineWidth=2;fg.beginPath();fg.moveTo(x,y);for(let j=1;j<7;j++)fg.lineTo(x+j*7,y+Math.sin(t*1.3+j*.8+i)*2);fg.stroke();}for(const x of [172,333]){fg.strokeStyle='#d3f3de77';fg.lineWidth=2;fg.beginPath();fg.ellipse(x,238,15+Math.sin(t*2+x)*3,4,0,0,Math.PI*1.7);fg.stroke();}}
 const p=profile?.appearance||appearance;character(fg,256,fishY,p,'down',fishState==='walking'?t*13:0,2.25);
 // Galvanised catch bucket stays beside the character, with visible fish as it fills.
 sprite(fg,'bucket',311,174,33,36);
 if(fishState==='idle'){for(let i=0;i<rippleSpots.length;i++){const p=rippleSpots[i],fade=Math.min(1,p.age/.45,(p.life-p.age)/.7);for(let j=0;j<3;j++){const a=settings.ambient?(t*.65+j*.33+i*.17)%1:(j+1)/3;fg.strokeStyle=`rgba(230,255,233,${(1-a)*.8*fade})`;fg.lineWidth=2;fg.beginPath();fg.ellipse(p.x,p.y,8+a*27,3+a*10,0,0,Math.PI*2);fg.stroke();}}}
 if(['casting','waiting','reeling','caught'].includes(fishState)){const casting=fishState==='casting',fraction=casting?Math.min(1,fishTimer/.9):1,rodX=274,rodY=fishY-32,tipX=298,tipY=fishY-70+(casting?Math.sin(fraction*Math.PI)*-20:0),float=lurePoint(t),endX=rodX+(float.x-rodX)*fraction,endY=rodY+(float.y-rodY)*fraction-(casting?Math.sin(fraction*Math.PI)*60:0);fg.strokeStyle='#4d3429';fg.lineWidth=4;fg.beginPath();fg.moveTo(rodX,rodY);fg.quadraticCurveTo(292,fishY-60,tipX,tipY);fg.stroke();fg.strokeStyle='#f2e5b9b0';fg.lineWidth=1;fg.beginPath();fg.moveTo(tipX,tipY);fg.lineTo(endX,endY);fg.stroke();if(fishState!=='caught'){fg.fillStyle='#f5e7c3';fg.fillRect(endX-3,endY-7,6,7);fg.fillStyle='#cf583c';fg.fillRect(endX-3,endY-3,6,4);}}
 if(alertTime>0&&fishState==='reeling'){fg.fillStyle='#f9e6a4';fg.fillRect(251,fishY-108,10,26);fg.fillRect(251,fishY-77,10,8);}
 drawLureSplash();if(fishState==='reeling'){// The first basic rod has a visible reel which turns while held.
 const rx=278,ry=fishY-27,ang=reeling&&!lineLocked?t*9:0;fg.fillStyle='#524137';fg.fillRect(rx-7,ry-7,14,14);fg.fillStyle='#c6b990';fg.fillRect(rx-5,ry-5,10,10);fg.strokeStyle='#4c4437';fg.lineWidth=2;fg.beginPath();fg.moveTo(rx,ry);fg.lineTo(rx+Math.cos(ang)*8,ry+Math.sin(ang)*8);fg.stroke();}
}

// Island time advances only during active play; nobody misses a boat while away.
function freshEconomy(){return {coins:120,time:0,stock:{food:0,water:0,bait:0},owned:{sunglasses:false,striped:false,tropical:false,line:false},records:{mackerel:{count:0,best:0},pollock:{count:0,best:0}}};}
let economy=freshEconomy(),lastBoatMinute=-1,editingCharacter=false,boatSignature='';
const boatServices=[{id:'trader',name:'Trader',weekday:3,duration:240},{id:'shop',name:'Shop',weekday:5,duration:240},{id:'ferry',name:'Ferry',weekday:1,duration:240}];
function boatState(id){const s=boatServices.find(s=>s.id===id),t=economy.time;if(t<s.first)return {active:false,in:s.first-t,left:0};const phase=(t-s.first)%s.period;return {active:phase<s.duration,in:phase<s.duration?0:s.period-phase,left:Math.max(0,s.duration-phase)};}
function islandTime(after=0){const m=Math.floor(480+economy.time+after),day=Math.floor(m/1440)+1,h=Math.floor(m%1440/60),min=m%60;return `Day ${day} · ${String(h).padStart(2,'0')}:${String(min).padStart(2,'0')}`;}
function loadEconomy(value){economy=freshEconomy();if(value&&typeof value==='object'){for(const k of ['coins','time'])if(Number.isFinite(value[k])&&value[k]>=0&&value[k]<=1e9)economy[k]=k==='coins'?Math.floor(value[k]):value[k];for(const k of ['food','water','bait'])if(Number.isSafeInteger(value.stock?.[k])&&value.stock[k]>=0)economy.stock[k]=value.stock[k];for(const k of ['sunglasses','striped','tropical','line'])economy.owned[k]=value.owned?.[k]===true;for(const id of ['mackerel','pollock']){const record=value.records?.[id];if(Number.isSafeInteger(record?.count)&&record.count>=0)economy.records[id].count=record.count;if(Number.isFinite(record?.best)&&record.best>=0&&record.best<200)economy.records[id].best=record.best;}}
 for(const id of ['mackerel','pollock']){const old=bucket.filter(c=>c.species===id);economy.records[id].count=Math.max(economy.records[id].count,old.length);economy.records[id].best=Math.max(economy.records[id].best,...old.map(c=>c.size),0);}lastBoatMinute=-1;
}
function tickBoats(dt){if((screen==='game'||screen==='fishing')&&$('modal').classList.contains('hidden')){economy.time+=dt;if(Math.floor(economy.time)!==lastBoatMinute){lastBoatMinute=Math.floor(economy.time);updateBoatBoard();if(lastBoatMinute%15===0)persist();}}}
function updateBoatBoard(){if(!profile)return;$('coinCount').textContent=economy.coins;$('boatClock').textContent=islandTime();let next=boatServices.map(s=>({...s,...boatState(s.id)})).sort((a,b)=>a.in-b.in)[0];$('nextBoat').textContent=next.active?`${next.name} is here`:`${next.name} in ${Math.ceil(next.in)}m`;
 for(const s of boatServices){const state=boatState(s.id),b=$('visit-'+s.id);b.textContent=state.active?`${s.name} · Here for ${Math.ceil(state.left)}m`:`${s.name} · ${islandTime(state.in)}`;b.classList.toggle('boat-here',state.active);b.setAttribute('aria-label',state.active?`Visit ${s.name}`:`${s.name} due ${islandTime(state.in)}`);}const signature=boatServices.map(s=>boatState(s.id).active).join(',');if(signature!==boatSignature){boatSignature=signature;renderLabels();}}
for(const service of boatServices)$('visit-'+service.id).onclick=()=>{const state=boatState(service.id);if(state.active){const spot=spots.find(s=>s.id===service.id);goSpot(spot);$('boatPopup').classList.add('hidden');}else modal(service.name+' timetable',`<p>Next arrival: <b>${islandTime(state.in)}</b>.</p><p>Stays for ${service.duration} island minutes.</p><p class="mini-note">Island time runs at three minutes per second of active play and pauses while you are away or viewing a menu.</p>`,'AT THE LANDING');};
function valueOfFish(c){return Math.max(1,Math.round(c.size*(c.species==='mackerel'?.45:.6)));}
function sellFish(species=null){if(!boatState('trader').active)return false;let value=0,remaining=[];for(const c of bucket){if(!species||c.species===species)value+=valueOfFish(c);else remaining.push(c);}if(!value)return false;bucket=remaining;economy.coins+=value;persist();updateBoatBoard();openTrader(`Sold your fish for ${value} coins.`);return true;}
const shopItems=[{id:'food',name:'Picnic snack',price:6,detail:'A little something to eat by the sea.',kind:'stock'},{id:'water',name:'Drinking water',price:4,detail:'A bottle for a quiet break.',kind:'stock'},{id:'sunglasses',name:'Sunglasses',price:35,detail:'Wear them on the island and fishing pier.',kind:'cosmetic'},{id:'striped',name:'Striped shirt',price:45,detail:'A classic seaside outfit.',kind:'cosmetic'},{id:'tropical',name:'Fancy flower shirt',price:60,detail:'A brighter look for your island days.',kind:'cosmetic'}];
const traderItems=[{id:'bait',name:'Five bait portions',price:12,amount:5,detail:'Used automatically on casts. Fish bite sooner.',kind:'stock'},{id:'line',name:'Stronger fishing line',price:35,detail:'Tension builds 15% more slowly. A permanent upgrade.',kind:'upgrade'}];
function buyItem(id,service){if(!boatState(service).active)return false;const item=(service==='trader'?traderItems:shopItems).find(i=>i.id===id);if(!item||(item.kind==='stock'&&(economy.stock[id]||0)+(item.amount||1)>10)||economy.coins<item.price||(item.kind!=='stock'&&economy.owned[id]))return false;economy.coins-=item.price;if(item.kind==='stock')economy.stock[id]+=item.amount||1;else{economy.owned[id]=true;if(id==='sunglasses'){profile.appearance.glasses=true;profile.appearance.eyewear=2;}if(id==='striped'||id==='tropical')profile.appearance.pattern=id;}persist();updateBoatBoard();if(service==='trader')openTrader(`${item.name} added to your kit.`);else openShop(`${item.name} is yours.`);return true;}
function saleRows(items,service){return items.map(i=>`<div class="shop-item"><div><b>${i.name}</b><small>${i.detail}</small></div><button id="buy-${i.id}" ${economy.coins<i.price||!packFits(i.id,i.amount||1)||(i.kind!=='stock'&&economy.owned[i.id])?'disabled':''}>${i.kind!=='stock'&&economy.owned[i.id]?'Owned':!packFits(i.id,i.amount||1)?'Pack full':i.price+' ●'}</button></div>`).join('');}
function wirePurchases(items,service){for(const i of items)$('buy-'+i.id).onclick=()=>buyItem(i.id,service);}
function openTrader(message=''){if(!boatState('trader').active){modal('The trader is at sea','<p>Check the timetable for the next visit. Your fish will keep safely in the bucket.</p>');return;}const total=bucket.reduce((sum,c)=>sum+valueOfFish(c),0);modal('A fair trade',`${message?`<p class="trade-message">${message}</p>`:''}<p><b>${economy.coins} coins</b> · ${bucket.length} fish in your bucket</p><button class="action gold" id="sell-all" ${!bucket.length?'disabled':''}>Sell all fish · ${total} coins</button>${fishSpecies.map(f=>{const group=bucket.filter(c=>c.species===f.id);return group.length?`<button class="action" id="sell-${f.id}">Sell ${group.length} ${f.name.toLowerCase()} · ${group.reduce((n,c)=>n+valueOfFish(c),0)} coins</button>`:'';}).join('')}<p class="mini-note">Your species discoveries and personal bests remain in your journal after selling.</p><h3>Fishing supplies</h3>${saleRows(traderItems,'trader')}`,'THE TRADER');$('sell-all').onclick=()=>sellFish();for(const f of fishSpecies)if(bucket.some(c=>c.species===f.id))$('sell-'+f.id).onclick=()=>sellFish(f.id);wirePurchases(traderItems,'trader');}
function openShop(message=''){if(!boatState('shop').active){modal('The shop boat is at sea','<p>Check the timetable for its next visit.</p>');return;}modal('A few island comforts',`${message?`<p class="trade-message">${message}</p>`:''}<p>You have <b>${economy.coins} coins</b>.</p>${saleRows(shopItems,'shop')}<p class="mini-note">New cosmetics are put on straight away. Change them at your shack. Food and water are for a relaxed break; there are no hunger or thirst meters.</p>`,'THE SHOP BOAT');wirePurchases(shopItems,'shop');}
function openFerry(){const state=boatState('ferry');modal(state.active?'The ferry is alongside':'The ferry is at sea',`<p>${state.active?'The crew are taking a short break at your landing.':`Next arrival: <b>${islandTime(state.in)}</b>.`}</p><p>The storm damaged the other island landings. Your dock is the first repaired, so mail and supplies can reach you again. Other routes will reopen as repairs progress.</p><p class="mini-note">Additional islands and route unlocks will be added in future releases.</p>`,'FERRY SERVICE');}
function openBag(message=''){modal('Your island bag',`${message?`<p class="trade-message">${message}</p>`:''}<p><b>${economy.coins} coins</b></p><button class="action" id="bagCatches">View ${bucket.length} fish in your bucket</button><div class="journal-row">Bait portions<span>${economy.stock.bait}</span></div><div class="shop-item"><span>Picnic snacks · ${economy.stock.food}</span><button id="eatSnack" ${!economy.stock.food?'disabled':''}>Enjoy one</button></div><div class="shop-item"><span>Water · ${economy.stock.water}</span><button id="drinkWater" ${!economy.stock.water?'disabled':''}>Have a drink</button></div><p class="mini-note">${economy.owned.line?'Stronger line fitted.':'Basic fishing line fitted.'}</p>`,'LITTLE COMFORTS');$('bagCatches').onclick=showBucket;$('eatSnack').onclick=()=>{if(economy.stock.food){economy.stock.food--;persist();openBag('A little snack and a moment watching the waves.');}};$('drinkWater').onclick=()=>{if(economy.stock.water){economy.stock.water--;persist();openBag('A refreshing drink in the sea air.');}};}
function openWardrobe(){modal('Your beach shack',`<p>A place to change your look.</p><button class="action" id="editLook">Change hair, colours & starter clothes</button><button class="action" id="wear-plain">Wear a plain shirt</button>${economy.owned.striped?'<button class="action" id="wear-striped">Wear your striped shirt</button>':''}${economy.owned.tropical?'<button class="action" id="wear-tropical">Wear your fancy flower shirt</button>':''}${economy.owned.sunglasses?`<button class="action" id="wear-glasses">${profile.appearance.glasses?'Take off':'Put on'} sunglasses</button>`:'<p class="mini-note">The shop boat sometimes brings new clothes and sunglasses.</p>'}`,'MAKE YOURSELF AT HOME');$('editLook').onclick=()=>{close();editingCharacter=true;appearance={...profile.appearance};$('name').value=profile.name;swatches();$('setSail').textContent='Save your look';show('creator');};for(const pattern of ['plain','striped','tropical'])if(pattern==='plain'||economy.owned[pattern])$('wear-'+pattern).onclick=()=>{profile.appearance.pattern=pattern;persist();openWardrobe();};if(economy.owned.sunglasses)$('wear-glasses').onclick=()=>{profile.appearance.glasses=!profile.appearance.glasses;profile.appearance.eyewear=profile.appearance.glasses?2:0;persist();openWardrobe();};}
function visitorBoat(kind,t,force=false){const active=boatState(kind).active;if(!active&&!force)return;const x=60,y=353+(settings.ambient?Math.sin(t*1.1)*1.5:0);ctx.save();ctx.translate(x,y);const hull=kind==='trader'?'#8c4f35':'#2e687f',awning=kind==='trader'?'#60885c':'#d39b4f';ctx.fillStyle='#133c4e55';ctx.fillRect(-24,13,49,5);ctx.fillStyle=hull;ctx.fillRect(-25,0,50,13);ctx.fillRect(-20,13,40,4);ctx.fillStyle='#e6d2a4';ctx.fillRect(-25,-2,50,4);ctx.fillStyle='#e9d7b3';ctx.fillRect(-17,-18,35,17);ctx.fillStyle=awning;ctx.fillRect(-21,-22,43,6);for(let i=0;i<4;i++){ctx.fillStyle='#f4e9cc';ctx.fillRect(-18+i*10,-22,5,6);}ctx.fillStyle='#315b6a';ctx.fillRect(-11,-12,8,7);ctx.fillRect(5,-12,8,7);ctx.fillStyle='#9b7549';ctx.fillRect(-11,2,8,7);ctx.fillRect(3,2,10,7);ctx.restore();waterRings(ctx,x,y+17,t,24);}

const START_DATE=Date.UTC(2026,5,1),DAY=1440,TIME_SPEED=3;
function freshRoutine(){return {food:100,water:100,location:'game',room:{x:256,y:580,dir:'up'},fridge:{bread:24,fruit:18,meal:12,water:30},bedMeal:false,pendingWake:0,collapseAt:1560,creatures:[],poolRecords:{crab:0,hermit:0,octopus:0},spoiledFood:0};}
let routine=freshRoutine(),sleeping=null,wakeBounce=0,lastLifeUI=-1,roomPath=[],roomTarget=null,roomWalking=false;
const foodTypes={food:{name:'Picnic snack',food:35,water:0},bread:{name:'Bread',food:30,water:0},fruit:{name:'Fruit',food:22,water:12},meal:{name:'Simple meal',food:50,water:5},water:{name:'Water',food:0,water:45}};
function absoluteMinute(){return 480+economy.time;}
function calendar(min=absoluteMinute()){const day=Math.floor(min/DAY),m=Math.floor(min%DAY),d=new Date(START_DATE+day*86400000);return {day,weekday:d.getUTCDay(),hour:m/60,minute:m,date:d,clock:`${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`,short:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d.getUTCDay()]};}
function dateText(min=absoluteMinute()){const c=calendar(min);return `${c.short} ${c.date.getUTCDate()} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][c.date.getUTCMonth()]} · ${c.clock}`;}
function nextMorning(min=absoluteMinute()){return (Math.floor((min-480)/DAY)+1)*DAY+480;}
function nextCollapse(min=absoluteMinute()){const d=Math.floor(min/DAY);return d*DAY+(min%DAY<480?120:1560);}
function loadRoutine(data){routine=freshRoutine();if(data&&typeof data==='object'){for(const k of ['food','water'])if(Number.isFinite(data[k]))routine[k]=Math.max(0,Math.min(100,data[k]));if(data.location==='house')routine.location='house';if(Number.isFinite(data.room?.x)&&Number.isFinite(data.room?.y)&&roomStand(data.room.x,data.room.y))routine.room={x:data.room.x,y:data.room.y,dir:'down'};for(const k of ['bread','fruit','meal','water'])if(Number.isSafeInteger(data.fridge?.[k])&&data.fridge[k]>=0)routine.fridge[k]=data.fridge[k];routine.bedMeal=data.bedMeal===true;if(Number.isFinite(data.collapseAt))routine.collapseAt=data.collapseAt;if(Number.isFinite(data.pendingWake))routine.pendingWake=data.pendingWake;if(Number.isSafeInteger(data.spoiledFood)&&data.spoiledFood>=0)routine.spoiledFood=data.spoiledFood;routine.creatures=Array.isArray(data.creatures)?data.creatures.filter(c=>poolSpecies.some(s=>s.id===c.species)&&Number.isFinite(c.size)&&c.size>0&&c.size<100&&typeof c.caughtAt==='string'):[];for(const id of ['crab','hermit','octopus'])routine.poolRecords[id]=Math.max(routine.creatures.filter(c=>c.species===id).length,Number.isSafeInteger(data.poolRecords?.[id])?Math.max(0,data.poolRecords[id]):0);
 }else{economy.stock.food=Math.max(2,economy.stock.food);economy.stock.water=Math.max(2,economy.stock.water);routine.collapseAt=nextCollapse();}for(const k of ['bread','fruit','meal'])economy.stock[k]=Number.isSafeInteger(economy.stock[k])&&economy.stock[k]>=0?economy.stock[k]:0;
 if(routine.pendingWake>0){economy.time=Math.max(economy.time,routine.pendingWake-480);routine.pendingWake=0;routine.location='house';routine.room={x:327,y:326,dir:'down'};routine.food=Math.max(70,routine.food);routine.water=Math.max(70,routine.water);routine.collapseAt=nextCollapse();}sleeping=null;roomPath=[];lastLifeUI=-1;
}
function updateLifeUI(){const c=calendar();$('greeting').textContent=dateText();$('lifeClock').textContent=c.clock;for(const k of ['food','water']){$('need-'+k).value=routine[k];$('need-'+k).classList.toggle('low',routine[k]<20);$('value-'+k).textContent=Math.ceil(routine[k])+'%';}$('lifeHUD').classList.toggle('hidden',!['game','fishing','house','pools','beach','forage','dock','woods','photo19'].includes(screen));}
function tickLife(dt){if(sleeping){updateSleep(dt);return true;}if(!['game','fishing','house','pools','beach','forage','dock','woods','photo19'].includes(screen)||!$('modal').classList.contains('hidden'))return false;economy.time+=dt*TIME_SPEED;routine.food=Math.max(0,routine.food-dt*TIME_SPEED*.055);routine.water=Math.max(0,routine.water-dt*TIME_SPEED*.06);wakeBounce=Math.max(0,wakeBounce-dt);if(absoluteMinute()>=routine.collapseAt||routine.food<=0||routine.water<=0){beginSleep(true);return true;}const minute=Math.floor(economy.time);if(minute!==lastLifeUI){lastLifeUI=minute;updateLifeUI();updateBoatBoard();if(minute%15<3)persist();}if(calendar().hour>=0&&calendar().hour<2&&routine.collapseAt-absoluteMinute()<120&&routine.collapseAt-absoluteMinute()>117&&screen==='game')notify('It is getting late. Head home before 2am.');return false;}
function nightLevel(){const h=calendar().hour;if(h>=8&&h<18)return 0;if(h>=18&&h<21)return (h-18)/3*.48;if(h>=21||h<5)return .48;if(h>=5&&h<8)return (8-h)/3*.48;return 0;}
function drawNight(g,indoors=false){const n=nightLevel()*(indoors?.38:1);if(!n)return;g.fillStyle=`rgba(9,21,51,${n})`;g.fillRect(0,0,W,H);if(!indoors&&g===ctx){g.fillStyle='#efbd6780';g.fillRect(352,245,6,8);}}
function consume(key,source='pack'){const item=foodTypes[key],stock=source==='fridge'?routine.fridge:economy.stock;if(!item||!stock[key])return false;stock[key]--;routine.food=Math.min(100,routine.food+item.food);routine.water=Math.min(100,routine.water+item.water);updateLifeUI();persist();return true;}
function packFromFridge(key){if(!routine.fridge[key])return false;const slots=Object.keys(foodTypes).concat('bait').filter(k=>(economy.stock[k]||0)>0).length;if((economy.stock[key]||0)>=10||(!(economy.stock[key]>0)&&slots>=6))return false;routine.fridge[key]--;economy.stock[key]=(economy.stock[key]||0)+1;persist();return true;}
function openFridge(message=''){modal('A well-stocked fridge',`${message?`<p class="trade-message">${message}</p>`:''}<p>Eat here or take a little food for the day.</p>${['bread','fruit','meal','water'].map(k=>`<div class="fridge-item"><b>${foodTypes[k].name} · ${routine.fridge[k]}</b><div><button id="eat-${k}" ${!routine.fridge[k]?'disabled':''}>${k==='water'?'Drink':'Eat'} now</button><button id="pack-${k}" ${!routine.fridge[k]?'disabled':''}>Pack one</button></div></div>`).join('')}<p class="mini-note">Backpack: six stacks, up to ten of each item. Food in the fridge is safe if you pass out.</p>`,'KITCHEN');for(const k of ['bread','fruit','meal','water']){$('eat-'+k).onclick=()=>{if(consume(k,'fridge'))openFridge('A little refreshed and ready for the island.');};$('pack-'+k).onclick=()=>openFridge(packFromFridge(k)?'Packed one for later.':'Your backpack stack is full.');}}
function spoilCarried(){for(const c of bucket)c.spoiled=true;for(const c of routine.creatures)c.spoiled=true;for(const k of ['food','bread','fruit','meal']){routine.spoiledFood+=economy.stock[k]||0;economy.stock[k]=0;}}
function beginSleep(forced=false){if(sleeping)return;reeling=false;poolHeld=null;close();roomPath=[];const from=absoluteMinute(),to=nextMorning(from);if(forced){spoilCarried();routine.bedMeal=true;}routine.pendingWake=to;routine.location='house';sleeping={from,to,elapsed:0,forced,lastSnore:-1};show('house');$('sleepOverlay').classList.remove('hidden');$('sleepReason').textContent=forced?'You dozed off… someone brought you safely home.':'A quiet night in your own bed.';$('sleepTime').textContent='Waking at 8am';drawSleepClock(0);persist();}
function snore(){if(!settings.sound||!biteAudio||biteAudio.state!=='running')return;try{const o=biteAudio.createOscillator(),g=biteAudio.createGain(),now=biteAudio.currentTime;o.type='sine';o.frequency.setValueAtTime(85,now);o.frequency.exponentialRampToValueAtTime?.(48,now+.45);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.025,now+.14);g.gain.exponentialRampToValueAtTime(.0001,now+.55);o.connect(g);g.connect(fxOutput());o.start(now);o.stop(now+.6);}catch(e){}}
function updateSleep(dt){if(!sleeping)return;sleeping.elapsed+=dt;const p=Math.min(1,sleeping.elapsed/12),ease=p*p*(3-2*p);economy.time=sleeping.from+(sleeping.to-sleeping.from)*ease-480;drawSleepClock(ease);$('sleepTime').textContent='Waking at 8am';$('sleepDay').textContent=calendar(sleeping.to).short+' · A peaceful night';const sn=Math.floor(sleeping.elapsed/1.5);if(sn!==sleeping.lastSnore){sleeping.lastSnore=sn;snore();}if(p>=1){const forced=sleeping.forced;sleeping=null;routine.pendingWake=0;routine.room={x:327,y:326,dir:'down'};routine.food=Math.max(70,routine.food);routine.water=Math.max(70,routine.water);routine.collapseAt=nextCollapse();wakeBounce=.8;$('sleepOverlay').classList.add('hidden');updateLifeUI();updateBoatBoard();persist();houseMessage(forced?'Morning. There is a plate of food beside your bed.':'Good morning. A new island day.');}}
const houseCanvas=$('houseCanvas'),hg=houseCanvas.getContext('2d'),houseArt=new Image();let houseReady=false;houseArt.onload=()=>{houseReady=true;};houseArt.src='assets/house.png';
const roomObstacles=[[72,178,241,253],[349,178,436,345],[73,354,141,500]];
function roomStand(x,y){return x>=77&&x<=435&&y>=260&&y<=590&&!roomObstacles.some(([a,b,c,d])=>x>a-8&&x<c+8&&y>b-3&&y<d+4);}
const roomSpots={bed:{x:326,y:308},fridge:{x:251,y:275},kitchen:{x:161,y:270},sofa:{x:166,y:460},exit:{x:256,y:586},meal:{x:327,y:363}};
function roomRoute(x,y){const cols=64,start={x:Math.round(routine.room.x/8),y:Math.round(routine.room.y/8)},goal={x:Math.round(x/8),y:Math.round(y/8)},key=p=>p.y*cols+p.x,prev=new Map([[key(start),null]]),queue=[start];let end=null;for(let i=0;i<queue.length;i++){const p=queue[i];if(Math.abs(p.x-goal.x)<=1&&Math.abs(p.y-goal.y)<=1){end=p;break;}for(const [dx,dy]of [[0,1],[1,0],[0,-1],[-1,0]]){const n={x:p.x+dx,y:p.y+dy},id=key(n);if(!prev.has(id)&&roomStand(n.x*8,n.y*8)){prev.set(id,p);queue.push(n);}}}const path=[];while(end&&prev.get(key(end))){path.push({x:end.x*8,y:end.y*8});end=prev.get(key(end));}return path.reverse();}
function enterHouse(){roomPath=[];routine.location='house';show('house');resizeScene(houseCanvas,$('houseWrap'));persist();}
function houseMessage(t){$('houseHint').textContent=t;}
function roomAction(id){roomTarget=id;const p=roomSpots[id];roomPath=roomRoute(p.x,p.y);if(!roomPath.length)finishRoomAction();}
function finishRoomAction(){const id=roomTarget;roomTarget=null;if(id==='bed'){unlockBiteAudio();modal('Turn in for the night?',`<p>Sleep until 8am. Your carried catches stay fresh when you sleep in your bed.</p><button class="action gold" id="sleepNow">Climb into bed</button>`,'SWEET DREAMS');$('sleepNow').onclick=()=>beginSleep(false);}if(id==='fridge'||id==='kitchen')openFridge();if(id==='exit'){routine.location='game';show('game');persist();}if(id==='sofa')houseMessage('A quiet seat by the sea.');if(id==='meal'&&routine.bedMeal){routine.bedMeal=false;routine.food=100;routine.water=100;updateLifeUI();persist();houseMessage('A warm breakfast and water. Fully refreshed.');}}
function updateRoom(dt){if(!$('modal').classList.contains('hidden'))return;roomWalking=roomPath.length>0;let budget=dt*145;while(roomPath.length&&budget>0){const p=roomPath[0],dx=p.x-routine.room.x,dy=p.y-routine.room.y,d=Math.hypot(dx,dy);routine.room.dir=facing(dx,dy,roomPath,routine.room,routine.room.dir);if(d<=budget){routine.room.x=p.x;routine.room.y=p.y;budget-=d;roomPath.shift();}else{routine.room.x+=dx/d*budget;routine.room.y+=dy/d*budget;budget=0;}}if(roomWalking&&!roomPath.length&&roomTarget)finishRoomAction();}
function resizeScene(c,wrap){const r=wrap.getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H);Object.assign(c.style,{left:(r.width-W*scale)/2+'px',top:(r.height-H*scale)/2+'px',width:W*scale+'px',height:H*scale+'px'});}
new ResizeObserver(()=>resizeScene(houseCanvas,$('houseWrap'))).observe($('houseWrap'));
houseCanvas.addEventListener('pointerdown',e=>{if(sleeping)return;const r=houseCanvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;if(x>348&&y>172&&y<350)return roomAction('bed');if(x>190&&x<245&&y>172&&y<258)return roomAction('fridge');if(y>586&&x>208&&x<305)return roomAction('exit');if(x>340&&x<430&&y>475&&y<536)return roomAction('chest');if(routine.bedMeal&&Math.hypot(x-327,y-363)<26)return roomAction('meal');if(!roomStand(x,y))return;roomTarget=null;roomPath=roomRoute(x,y);});
$('houseExit').onclick=()=>roomAction('exit');$('houseBed').onclick=()=>roomAction('bed');$('houseFridge').onclick=()=>roomAction('fridge');$('houseWardrobe').onclick=openWardrobe;
function drawHouse(t){hg.imageSmoothingEnabled=false;if(isPine13()&&cabinReady13)hg.drawImage(cabinArt13,0,0,W,H);else if(houseReady)hg.drawImage(houseArt,0,0,W,H);else{hg.fillStyle='#ad7942';hg.fillRect(60,120,400,500);}drawChest(hg);drawDecor(hg);if(sleeping){const a=profile.appearance;hg.fillStyle=palette.skin[a.skin];hg.fillRect(378,202,25,18);hg.fillStyle=palette.hair[a.hair];hg.fillRect(376,198,29,8);hg.fillStyle='#4a3c33';hg.fillRect(381,211,5,1);hg.fillRect(394,211,5,1);hg.fillStyle='#326b94';hg.fillRect(365,222+(settings.ambient?Math.sin(t*3):0),54,65);hg.font='bold 16px IslandRound';hg.fillStyle='#f8e7bc';hg.fillText('Z z z',390,181-(settings.ambient?Math.sin(t*2)*4:0));}else character(hg,routine.room.x,routine.room.y-(wakeBounce>0?Math.sin(wakeBounce/.8*Math.PI)*10:0),profile.appearance,routine.room.dir,roomWalking?t*14:0,2.75);if(routine.bedMeal){hg.fillStyle='#f5e6c1';hg.beginPath();hg.ellipse(327,363,17,8,0,0,Math.PI*2);hg.fill();hg.fillStyle='#d49b4b';hg.fillRect(318,357,17,7);hg.fillStyle='#6d9b58';hg.fillRect(329,355,7,5);}drawNight(hg,true);}

const poolSpecies=[{id:'crab',name:'Shore crab',colour:'#bd6747',speed:20,min:3,max:8},{id:'hermit',name:'Hermit crab',colour:'#b69a66',speed:10,min:2,max:5},{id:'octopus',name:'Small octopus',colour:'#a4779f',speed:30,min:8,max:20}];
const poolCanvas=$('poolCanvas'),pg=poolCanvas.getContext('2d'),poolArt=new Image();let poolReady=false,poolStones=[],poolAnimals=[],poolHeld=null,poolCaughtVisit=0,poolLastHint=0;poolArt.onload=()=>poolReady=true;poolArt.src='assets/pools-v8.png';
function newPoolStones(){poolAnimals=[];poolHeld=null;const coords=[[135,213],[277,205],[384,268],[164,334],[303,365],[128,460],[260,493],[390,502]];poolStones=coords.map(([x,y],i)=>({x,y,homeX:x,homeY:y,id:i,revealed:false,size:[.78,1.1,.87,1,.72,1.12,.85,.96][i],variant:i%4,empty:i===3||i===6}));$('poolRefresh').disabled=true;poolMessage('Slide a stone aside. Gently grab what you find.');}
function startPools(){path=[];poolCaughtVisit=0;newPoolStones();show('pools');resizeScene(poolCanvas,$('poolWrap'));updatePoolCount();}
function poolMessage(t){$('poolMessage').textContent=t;}
function updatePoolCount(){$('poolCount').textContent=routine.creatures.length;}
function revealStone(stone){if(stone.revealed)return;stone.revealed=true;if(stone.empty){poolMessage('A quiet patch of sand. Try another stone.');return;}const kind=poolSpecies[stone.id%3],angle=Math.random()*Math.PI*2;poolAnimals.push({kind:kind.id,x:stone.homeX,y:stone.homeY,age:0,wait:kind.id==='hermit'?3.5:1.7+Math.random(),life:12+Math.random()*4,dx:Math.cos(angle),dy:Math.sin(angle),caught:false,escaped:false,grace:0});poolMessage(`${kind.name}! Drag it into the bucket.`);}
function poolPointer(e){const r=poolCanvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H};}
poolCanvas.addEventListener('pointerdown',e=>grabPool(e));
poolCanvas.addEventListener('pointermove',e=>{if(!poolHeld)return;const p=poolPointer(e),item=poolHeld.item;item.x=Math.max(65,Math.min(470,p.x+poolHeld.dx));item.y=Math.max(125,Math.min(700,p.y+poolHeld.dy));if(poolHeld.type==='stone'&&Math.hypot(item.x-item.homeX,item.y-item.homeY)>17)revealStone(item);});
function releasePool(cancel=false){if(!poolHeld)return;const h=poolHeld;poolHeld=null;if(h.type==='animal'){const a=h.item;if(!cancel&&a.x>=370&&a.x<=491&&a.y>=595&&a.y<=730){const kind=poolSpecies.find(s=>s.id===a.kind),catchItem={species:kind.id,size:a.size||Math.round((kind.min+Math.random()*(kind.max-kind.min))*10)/10,tone:a.tone||0,caughtAt:new Date().toISOString(),spoiled:false};routine.creatures.push(catchItem);routine.poolRecords[kind.id]++;a.caught=true;poolCaughtVisit++;poolMessage(`${kind.name} · ${catchItem.size.toFixed(1)} cm · safely in the bucket!`);updatePoolCount();persist();}else{a.x=Math.max(90,Math.min(424,a.x));a.y=Math.max(165,Math.min(570,a.y));a.grace=.8;poolMessage('It is back in the pool. You can try again.');}}else{h.item.x=Math.max(88,Math.min(427,h.item.x));h.item.y=Math.max(160,Math.min(565,h.item.y));}}
