function showBucket(){modal('Your fishing bucket',bucket.length?bucket.slice().reverse().map(c=>`<div class="journal-row">${fishSpecies.find(f=>f.id===c.species).name}<span>${c.spoiled?'Spoiled':c.size.toFixed(1)+' cm'}</span></div>`).join(''):'<p>Your fish bucket is empty.</p>','YOUR CATCHES');}
