function reserveParcel(id,index){const r=routine.post.requests.find(r=>r.id===id);if(!r||r.status!=='finding'||nextCollection()>r.deadline)return false;const inv=requestInventory(r),c=inv[index];if(!c||!suitable(r,c))return false;r.parcel=inv.splice(index,1)[0];r.status='ready';r.pickupAt=nextCollection();persist();return true;}
