function validPatch(p){return p&&Array.isArray(p.depth)&&p.depth.length===BC*BR&&p.depth.every(n=>Number.isInteger(n)&&n>=0&&n<=10)&&Array.isArray(p.items)&&p.items.length<=12&&p.items.every(i=>i&&beachTypes[i.type]&&Number.isFinite(i.x)&&i.x>35&&i.x<480&&Number.isFinite(i.y)&&i.y>200&&i.y<620);}
