function serviceDays(id){return id==='shop'?[2,4,6]:[boatServices.find(s=>s.id===id).weekday];}
scheduledBoat=function(id){const c=calendar(),days=serviceDays(id),start=480,end=720;if(days.includes(c.weekday)&&c.minute>=start&&c.minute<end)return {scheduled:true,in:0,left:end-c.minute};let next=Infinity;for(const day of days){let ahead=(day-c.weekday+7)%7;if(!ahead&&c.minute>=end)ahead=7;next=Math.min(next,ahead*DAY+start-c.minute);}return {scheduled:false,in:next,left:0};};
