const movingSurfaceV9=movingSurface;movingSurface=function(g,base,t,mask=null,fromY=0){if(base!==beachBase)return movingSurfaceV9(g,base,t,mask,fromY);if(!settings.ambient)return;const frames=prepareWaterFrames(base,beachWaterMask,0),position=(t%4.8)/4.8*frames.length,index=Math.floor(position),fraction=position-index;g.save();g.beginPath();g.rect(0,0,W,110);g.clip();g.globalAlpha=1;g.drawImage(frames[index],0,0,W,H);g.globalAlpha=fraction;g.drawImage(frames[(index+1)%frames.length],0,0,W,H);g.restore();};
