 const container=(source,title)=>`<section class="inventory-container ${['fridge','freezer'].includes(source)?'fridge-appliance':''} ${source==='pack'?'backpack-panel':''}" data-inventory-container="${source}" tabindex="0" aria-label="${source==='pack'?'Backpack':source}">${source==='fridge'?'<div class="open-fridge-door" aria-hidden="true"><i></i><i></i><i></i></div><div class="fridge-light" aria-hidden="true"></div>':''}<h3>${uiIcon(source==='pack'?'bag':['fridge','freezer'].includes(source)?'fridge':source==='chest'?'chest':'mail')} ${title}<small>${source==='pack'?packUsed()+'/12':['fridge','freezer'].includes(source)?coldUsed(source)+'/'+(source==='fridge'?24:source==='freezer'?48:COLD_SLOTS):''}</small></h3><div class="inventory-grid" id="inventory-${source}"></div>${source==='fridge'?'<div class="crisper-drawers" aria-hidden="true"><i></i><i></i></div>':''}</section>`;
