function shipHorn(){if(!audioPrefs.fx||!audioUnlocked||!biteAudio||biteAudio.state!=='running')return;try{const now=biteAudio.currentTime;for(const hz of [174,220]){const o=biteAudio.createOscillator(),g=biteAudio.createGain();o.type='sine';o.frequency.setValueAtTime(hz,now);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.065,now+.12);g.gain.exponentialRampToValueAtTime(.0001,now+.8);o.connect(g);g.connect(fxOutput());o.start(now);o.stop(now+.82);}}catch(e){}}
