drawHouse=function(t){hg.imageSmoothingEnabled=false;if(isPine13()&&cabinReady13)hg.drawImage(cabinArt13,0,0,W,H);else if(houseReady)hg.drawImage(houseArt,0,0,W,H);else{hg.fillStyle='#ad7942';hg.fillRect(60,120,400,500);}drawChest(hg);drawDecor(hg);const a=profile.appearance;if(bedEntrance&&sleeping){const p=Math.min(1,(sleeping.entry||0)/1.8),ease=p*p*(3-2*p);character(hg,bedEntrance.x+(391-bedEntrance.x)*ease,bedEntrance.y+(260-bedEntrance.y)*ease,a,'up',t*10,2.75);if(p>.65){hg.fillStyle='#326b94';hg.fillRect(365,245,54,42);}}else if(sleeping){hg.fillStyle=palette.skin[a.skin];hg.fillRect(378,202,25,18);hg.fillStyle=palette.hair[a.hair];hg.fillRect(376,198,29,8);hg.fillStyle='#4a3c33';hg.fillRect(381,211,5,1);hg.fillRect(394,211,5,1);hg.fillStyle='#326b94';hg.fillRect(365,222+(settings.ambient?Math.sin(t*3):0),54,65);hg.font='bold 16px IslandRound';hg.fillStyle='#f8e7bc';hg.fillText('Z z z',390,181-(settings.ambient?Math.sin(t*2)*4:0));}else if(wakeAnimation>0){const elapsed=2.8-wakeAnimation,x=elapsed<1.9?391:391-(elapsed-1.9)/.9*64,y=elapsed<1.9?270:270+(elapsed-1.9)/.9*56;character(hg,x,y,a,'down',elapsed>1.9?t*12:0,2.75);if(elapsed<1.9){hg.save();hg.translate(x,y);hg.scale(2.75,2.75);hg.fillStyle=palette.skin[a.skin];const lift=Math.sin(Math.min(1,elapsed/1.4)*Math.PI)*8;hg.fillRect(-10,-14-lift,4,8);hg.fillRect(7,-14-lift,4,8);hg.fillStyle='#754d3d';hg.fillRect(-2,-18,4,4);hg.restore();}}else character(hg,routine.room.x,routine.room.y,a,routine.room.dir,roomWalking?t*14:0,2.75);if(routine.bedMeal){hg.fillStyle='#f5e6c1';hg.beginPath();hg.ellipse(327,363,17,8,0,0,Math.PI*2);hg.fill();hg.fillStyle='#d49b4b';hg.fillRect(318,357,17,7);}drawNight(hg,true);};

