 if(a.top===1){r('#f7ebc9',-3,-16,2,2);r('#f7ebc9',1,-16,2,2);r(ink,0,-12,1,1);r(ink,0,-9,1,1);}
 r(a.top===2?shirt:skin,-8,-14-swing,3,6);r(a.top===2?shirt:skin,5,-14+swing,3,6);r(skin,-8,-9-swing,3,2);r(skin,5,-9+swing,3,2);
 if(a.style===2){r(ink,-9,-27,4,16);r(ink,5,-27,4,16);r(hair,-8,-26,3,14);r(hair,5,-26,3,14);}
 r(ink,-6,-31,12,2);r(ink,-8,-29,16,12);r(ink,-6,-17,12,2);
