 if(a.style===2){r(hair,-9,-24,3,12);r(hair,6,-24,3,12);r(hair,-5,-26,6,2);}
 if(a.style===3){for(const [xx,yy]of [[-8,-29],[-5,-32],[-1,-33],[3,-32],[6,-29]])r(hair,xx,yy,4,5);r(hair,-8,-24,3,6);r(hair,5,-24,3,6);}
 if(a.style===4){r(skin,-6,-26,12,3);r(hair,-6,-29,12,3);}
