   r(ink,-4,-22,2,blink?1:3);r(ink,3,-22,2,blink?1:3);if(!blink){r('#fff2d8',-4,-22,1,1);r('#fff2d8',3,-22,1,1);}r('#d8827244',-6,-19,3,2);r('#d8827244',4,-19,3,2);r('#a36557',-1,-17,2,1);
