renderPortrait=function(){const g=$('portrait').getContext('2d'),t=clock,a=normaliseLook(appearance),dance=settings.ambient&&previewDance>t,wave=settings.ambient&&!dance&&t%15>10&&t%15<12.5;g.clearRect(0,0,180,400);g.imageSmoothingEnabled=false;g.fillStyle='#7d937d33';g.beginPath();g.ellipse(90,310,55,9,0,0,Math.PI*2);g.fill();g.save();g.translate(90+(dance?Math.sin(t*8)*8:0),307+(dance?-Math.abs(Math.sin(t*7))*13:settings.ambient?Math.sin(t*1.8)*1.4:0));if(dance)g.rotate(Math.sin(t*7)*.09);g.scale(6.8,6.8);character(g,0,0,a,'down',dance?t*14:0,1);if(wave||dance){g.fillStyle=palette.skin[a.skin];g.fillRect(7,-20,3,7);g.fillRect(8+Math.round(Math.sin(t*13)),-24,3,4);}g.restore();};

