npcGreeting=function(id){if(id==='mara'){if(routine.shrineSeen)return 'Your grandparents always had time for this place. The trees, the neighbours… even my stories about horses.';if(islandProgress().discoveries>=3)return 'You notice the little things. Good quality in a neighbour. And in a horse, actually.';return 'A few useful things, a few curious things. If I start talking about horses, you’re allowed to interrupt.';}if(id==='pip'){if(routine.craftedCount>0)return 'You made that yourself? Lovely. I hauled my stock across the sound and you’ve become competition.';if(Object.values(routine.decor).some(Boolean))return 'The shack is coming along beautifully. I may have something that would suit it. Purely a professional observation.';return 'All this lifting before lunch. Honestly. Still, I did bring that little something you might like.';}if(routeOpen13())return 'Pinewatch’s landing is clear. Fancy a crossing? I’ve just about finished the next three things.';if(routine.shrineSeen)return 'Your grandparents looked after that grove. Always made time for it, even when everything else needed doing.';return 'Warm springs, cold currents, weather with a mind of its own. These islands never did agree on the forecast.';};
talkNpc=function(id,after){if(!NPCS[id]||!boatState(NPCS[id].service).active)return false;routine.npcMet||={};const first=!routine.npcMet[id];routine.npcMet[id]=true;if(id==='nell')introduceRoute();persist();const lines=first?{mara:['Bruce. Good to see the shack lived in again. Your grandparents were good people.', 'I trade supplies and things I come across. No horses aboard today. Nat was very firm about that.',npcGreeting(id)],pip:['Katie. I run the shop boat. Apparently that includes carrying everything myself.', 'It is lovely to have someone back here, though. Tell me what you need and I’ll see what I can find.',npcGreeting(id)],nell:['Nat! Ferry, post, occasional runaway parcel. I keep things moving.', 'The islands are a curious bunch. Deep currents, warm springs and the strangest pockets of weather. You’ll see.',npcGreeting(id)]}[id]:[npcGreeting(id)];let index=0;const paint=()=>{modal(NPCS[id].name,npcSpeech(id,lines[index])+`<button id="npcNext" class="action gold">${index<lines.length-1?'Continue':'See you soon'}</button>`,NPCS[id].role);$('npcNext').onclick=()=>{if(index<lines.length-1){index++;paint();}else if(after)after();else close();};};paint();return true;};
